    );
  }
  return null;
};

const BalanceChart: React.FC<BalanceChartProps> = ({ benchmarkMode = 'USD' }) => {

  // --- DATA GENERATION ---
  const chartData = useMemo(() => {
    const data = [];
    const now = new Date();
    const daysToShow = 7;
    const pointsPerDay = 4; // 6-hour intervals
    const totalPoints = daysToShow * pointsPerDay;

    // Initial Base values
    let ethPrice = 3100;
    let solPrice = 135;
    let pepePrice = 0.000010;
    let bnbPrice = 580.00;
    let usdcBalance = 2500; 
    let usdtBalance = 3485554;

    const ethQty = 350;
    const solQty = 45;
    const pepeQty = 900000000;
    const bnbQty = 120000;

    let startTotal = 0;
    let startBenchmark = 0;

    for (let i = 0; i <= totalPoints; i++) {
      const date = new Date(now.getTime() - ((totalPoints - i) * (24/pointsPerDay) * 60 * 60 * 1000));

      // Random walk simulation
      ethPrice = ethPrice * (1 + (Math.random() - 0.48) * 0.02); 
      solPrice = solPrice * (1 + (Math.random() - 0.48) * 0.04);
      pepePrice = pepePrice * (1 + (Math.random() - 0.45) * 0.08);
      bnbPrice = bnbPrice * (1 + (Math.random() - 0.48) * 0.015);

      // Force end values to match Dashboard mock data
      if (i === totalPoints) {
         ethPrice = 3208.93;
         solPrice = 142.50;
         pepePrice = 0.000012;
         bnbPrice = 592.50;
      }

      const ethVal = ethPrice * ethQty;
      const solVal = solPrice * solQty;
      const pepeVal = pepePrice * pepeQty;
      const bnbVal = bnbPrice * bnbQty;
      const total = ethVal + solVal + pepeVal + bnbVal + usdcBalance + usdtBalance;

      // Benchmark Logic
      let benchmarkPrice = ethPrice; 
      if (benchmarkMode === 'BTC') {
         benchmarkPrice = ethPrice * 0.8 + (Math.random() * 500); 
      }

      if (i === 0) {
          startTotal = total;
          startBenchmark = benchmarkPrice;
      }

      // Exact Breakdown for Tooltip with BRAND SPECIFIC COLORS (Matches constants.tsx)
      const breakdown = [
        { name: 'BNB', value: bnbVal, change: ((bnbPrice - 580)/580)*100, color: '#F3BA2F' }, // BNB Gold
        { name: 'USDT', value: usdtBalance, change: 0, color: '#26A17B' }, // USDT Teal
        { name: 'ETH', value: ethVal, change: ((ethPrice - 3100)/3100)*100, color: '#627EEA' }, // ETH Indigo
        { name: 'SOL', value: solVal, change: ((solPrice - 135)/135)*100, color: '#14F195' }, // SOL Neon Cyan
        { name: 'PEPE', value: pepeVal, change: ((pepePrice - 0.000010)/0.000010)*100, color: '#4C9540' }, // PEPE Forest Green
        { name: 'USDC', value: usdcBalance, change: 0, color: '#2775CA' } // USDC Science Blue
      ];

      // Value Calculation
      let plotValue = total;
      let benchmarkPlotValue = 0;

      if (benchmarkMode !== 'USD') {
          plotValue = ((total - startTotal) / startTotal) * 100;
          const rawBenchmarkChange = ((benchmarkPrice - startBenchmark) / startBenchmark) * 100;
          benchmarkPlotValue = rawBenchmarkChange - 1.2; 
      }

      data.push({
        timestamp: date.getTime(),
        shortDate: new Intl.DateTimeFormat('en-US', { month: 'short', day: 'numeric' }).format(date),
        fullDate: new Intl.DateTimeFormat('en-US', { month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' }).format(date),
        value: plotValue,
        benchmarkValue: benchmarkPlotValue,
        breakdown: breakdown
      });
    }
    return data;
  }, [benchmarkMode]);

  return (
    <ResponsiveContainer width="100%" height="100%">
      <AreaChart data={chartData} margin={{ top: 20, right: 0, left: 0, bottom: 0 }}>
        <defs>
          <linearGradient id="chartGradient" x1="0" y1="0" x2="0" y2="1">
            <stop offset="0%" stopColor="#10b981" stopOpacity={0.2}/>
            <stop offset="100%" stopColor="#10b981" stopOpacity={0}/>
          </linearGradient>
        </defs>

        {/* Grid with lower opacity */}
        <CartesianGrid vertical={false} stroke="#27272a" strokeDasharray="3 3" opacity={0.2} />

        <XAxis 
          dataKey="shortDate" 
          axisLine={false}
          tickLine={false}
          tick={{ fill: '#71717a', fontSize: 10, fontWeight: 700, textTransform: 'uppercase' }}
          interval={3} 
          dy={10}
        />

        <YAxis hide domain={['auto', 'auto']} />

        <Tooltip 
          content={<RichTooltip benchmarkMode={benchmarkMode} />} 
          cursor={{ stroke: '#FFFFFF', strokeWidth: 1, strokeOpacity: 0.2, strokeDasharray: '4 4' }} 
        />

        {benchmarkMode !== 'USD' && (
            <Line 
                type="monotone"
                dataKey="benchmarkValue"
                stroke="#52525b" 
                strokeWidth={2}
                strokeDasharray="4 4"
                dot={false}
                animationDuration={1500}
            />
        )}

        <Area 
          type="monotone" // Smoothed but precise (not natural)
          dataKey="value" 
          stroke="#10b981" 
          strokeWidth={2} // Refined stroke width
          fill={benchmarkMode === 'USD' ? "url(#chartGradient)" : "none"} 
          animationDuration={1500}
          activeDot={{ 
            r: 4, 
            fill: '#10b981', 
            stroke: '#050505', 
            strokeWidth: 2 
          }}
        />
      </AreaChart>
    </ResponsiveContainer>
  );
};

